frappe.query_reports['Employee Attendance Schedule'] = {
    onload: function(report) {
        apply_attendance_cutoff(report);
    },
    filters: [
        {
            fieldname: 'employee',
            label: __('Employee'),
            fieldtype: 'Link',
            options: 'Employee',
            reqd: 1,
            get_query: function() {
                return { filters: { status: 'Active' } };
            },
            on_change: function() {
                var emp = frappe.query_report.get_filter_value('employee');
                if (emp) {
                    frappe.db.get_value('Employee', emp, 'employee_name', function(r) {
                        if (r && r.employee_name) {
                            frappe.query_report.set_filter_value('employee_name', r.employee_name);
                        }
                    });
                }
            }
        },
        {
            fieldname: 'employee_name',
            label: __('Employee Name'),
            fieldtype: 'Data',
            read_only: 1
        },
        {
            fieldname: 'cutoff_period',
            label: __('Cutoff'),
            fieldtype: 'Select',
            options: [
                { value: 'auto', label: __('Current Cutoff') },
                { value: 'first', label: __('23-7 / Pay 15') },
                { value: 'second', label: __('8-22 / Pay 30') }
            ],
            default: 'auto',
            on_change: function() {
                apply_attendance_cutoff(frappe.query_report);
            }
        },
        {
            fieldname: 'from_date',
            label: __('From Date'),
            fieldtype: 'Date',
            reqd: 1
        },
        {
            fieldname: 'to_date',
            label: __('To Date'),
            fieldtype: 'Date',
            reqd: 1
        },
        {
            fieldname: 'pay_day',
            label: __('Pay Day'),
            fieldtype: 'Date',
            read_only: 1
        }
    ]
};

function apply_attendance_cutoff(report) {
    if (!report) return;

    var selected = report.get_filter_value('cutoff_period') || 'auto';
    var today = frappe.datetime.str_to_obj(frappe.datetime.get_today());
    var year = today.getFullYear();
    var month = today.getMonth();
    var day = today.getDate();

    if (selected === 'auto') {
        selected = day <= 7 || day >= 23 ? 'first' : 'second';
    }

    var fromDate;
    var toDate;
    var payDay;

    if (selected === 'first') {
        if (day <= 7) {
            fromDate = new Date(year, month - 1, 23);
            toDate = new Date(year, month, 7);
            payDay = new Date(year, month, 15);
        } else {
            fromDate = new Date(year, month, 23);
            toDate = new Date(year, month + 1, 7);
            payDay = new Date(year, month + 1, 15);
        }
    } else {
        fromDate = new Date(year, month, 8);
        toDate = new Date(year, month, 22);
        payDay = new Date(year, month, Math.min(30, new Date(year, month + 1, 0).getDate()));
    }

    report.set_filter_value('from_date', frappe.datetime.obj_to_str(fromDate));
    report.set_filter_value('to_date', frappe.datetime.obj_to_str(toDate));
    report.set_filter_value('pay_day', frappe.datetime.obj_to_str(payDay));
}
